<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { adminApi } from '@/api';
import { useToast } from '@/stores/toast';

const CODE_LABELS = { MORNING: 'Sáng', AFTERNOON: 'Chiều', EVENING: 'Tối' };
const toast = useToast();
const attendanceView = ref('attendance');
const users = ref([]);
const attendance = ref([]);
const attendanceMonth = ref(dateKey(new Date()).slice(0, 7));
const attendanceStatus = ref('PENDING');
const attendanceUserId = ref('');
const attendanceLoading = ref(false);
const attendanceError = ref('');
const attendanceSavingId = ref(null);
const rateUserId = ref('');
const payRates = ref([]);
const rateError = ref('');
const rateSaving = ref(false);
const rateForm = ref({ effectiveFrom: dateKey(new Date()), regularHourlyRate: null, overtimeHourlyRate: null });
let attendanceGeneration = 0;
let rateGeneration = 0;
const staff = computed(() => users.value.filter(user => user.roleName === 'STAFF' && (user.status || 'ACTIVE') === 'ACTIVE'));
const monthResult = computed(() => ({ total: attendance.value.filter(item => item.paySnapshotStatus === 'CALCULATED').reduce((sum,item)=>sum+Number(item.totalPayAmount||0),0), pending: attendance.value.filter(item => item.attendanceStatus === 'PENDING').length, missing: attendance.value.filter(item => item.attendanceStatus === 'PENDING' && item.effectiveRegularHourlyRate == null).length, legacy: attendance.value.filter(item => item.paySnapshotStatus === 'LEGACY_UNAVAILABLE').length }));
const money = value => Number(value).toLocaleString('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0});

function dateKey(date) { return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`; }
async function loadUsers() { try { const data = await adminApi.getUsers(); users.value = Array.isArray(data) ? data : []; } catch (error) { attendanceError.value = error.message || 'Không thể tải nhân viên'; } }
async function loadAttendance() {
  const generation = ++attendanceGeneration;
  const requested = `${attendanceMonth.value}|${attendanceStatus.value}|${attendanceUserId.value}`;
  attendanceLoading.value = true;
  attendanceError.value = '';
  try {
    const data = await adminApi.getShiftAttendance({ month: attendanceMonth.value, status: attendanceStatus.value || undefined, userId: attendanceUserId.value ? Number(attendanceUserId.value) : undefined });
    if (generation !== attendanceGeneration || requested !== `${attendanceMonth.value}|${attendanceStatus.value}|${attendanceUserId.value}`) return;
    attendance.value = Array.isArray(data) ? data : [];
  } catch (error) {
    if (generation === attendanceGeneration && requested === `${attendanceMonth.value}|${attendanceStatus.value}|${attendanceUserId.value}`) attendanceError.value = error.message || 'Không thể tải chấm công';
  } finally { if (generation === attendanceGeneration) attendanceLoading.value = false; }
}
async function loadRates() { const generation=++rateGeneration;rateError.value='';if(!rateUserId.value){payRates.value=[];return;}try{const data=await adminApi.getStaffPayRates(Number(rateUserId.value));if(generation===rateGeneration)payRates.value=Array.isArray(data)?data:[];}catch(error){if(generation===rateGeneration)rateError.value=error.message||'Không thể tải mức công';} }
async function createRate() { if(rateSaving.value||!rateUserId.value)return;rateSaving.value=true;rateError.value='';try{await adminApi.createStaffPayRate(Number(rateUserId.value),{effectiveFrom:rateForm.value.effectiveFrom,regularHourlyRate:Number(rateForm.value.regularHourlyRate),overtimeHourlyRate:Number(rateForm.value.overtimeHourlyRate)});await loadRates();await loadAttendance();toast.success('Đã thêm mức công');}catch(error){rateError.value=error.status===409?'Ngày hiệu lực đã có mức công':error.message||'Không thể thêm mức công';}finally{rateSaving.value=false;} }
async function approve(item) {
  if (attendanceSavingId.value !== null) return;
  attendanceSavingId.value = item.shiftId;
  attendanceError.value = '';
  try {
    await adminApi.approveShiftAttendance(item.shiftId, { expectedUpdatedAt: item.updatedAt, approvedMinutes: Number(item.approvedMinutes ?? item.overlapEligibleMinutes), approvedOvertimeMinutes: Number(item.approvedOvertimeMinutes ?? item.potentialOvertimeMinutes), attendanceNote: item.attendanceNote || null });
    await loadAttendance();
    toast.success('Đã duyệt chấm công');
  } catch (error) {
    attendanceError.value = error.status === 409 ? 'Dữ liệu đã thay đổi. Danh sách đang được tải lại.' : error.message || 'Không thể duyệt chấm công';
    if (error.status === 409) await loadAttendance();
  } finally { attendanceSavingId.value = null; }
}
onMounted(async () => { await loadUsers(); await loadAttendance(); });
onUnmounted(() => { attendanceGeneration++; rateGeneration++; });
</script>

<template>
  <main class="attendance-page">
    <header class="page-header operations-studio-page-header"><div><p class="eyebrow">Nhân sự</p><h1>Chấm công & tiền công</h1><p>Đối chiếu giờ làm thực tế, duyệt công và quản lý mức tiền công theo hiệu lực.</p></div></header>
    <div class="attendance-mode-tabs view-tabs" role="tablist" aria-label="Chấm công và tiền công"><button role="tab" :aria-selected="attendanceView === 'attendance'" @click="attendanceView = 'attendance'">Duyệt chấm công</button><button role="tab" :aria-selected="attendanceView === 'rates'" @click="attendanceView = 'rates'">Mức tiền công</button></div>
    <template v-if="attendanceView === 'attendance'">
      <section class="attendance-summary-grid summary-grid" aria-label="Kết quả tháng"><article><span>Tổng ước tính đã duyệt</span><strong>{{ money(monthResult.total) }}</strong></article><article><span>Ca chờ duyệt</span><strong>{{ monthResult.pending }}</strong></article><article><span>Chờ mức công</span><strong>{{ monthResult.missing }} ca</strong></article><article><span>Legacy không snapshot</span><strong>{{ monthResult.legacy }} ca</strong></article></section>
      <section class="attendance-workspace panel" aria-labelledby="attendance-title">
        <div class="attendance-toolbar toolbar"><h2 id="attendance-title">Chấm công</h2><label>Tháng <input v-model="attendanceMonth" type="month" @change="loadAttendance"></label><label>Trạng thái <select v-model="attendanceStatus" class="form-select" @change="loadAttendance"><option value="">Tất cả</option><option value="PENDING">Chờ duyệt</option><option value="APPROVED">Đã duyệt</option></select></label><label>Nhân viên <select v-model="attendanceUserId" class="form-select" @change="loadAttendance"><option value="">Tất cả</option><option v-for="user in staff" :key="user.userId" :value="String(user.userId)">{{ user.fullName }}</option></select></label><button class="btn btn-outline" type="button" :disabled="attendanceLoading" @click="loadAttendance">Làm mới</button></div>
        <div v-if="attendanceError" class="state error" role="alert">{{ attendanceError }} <button class="btn btn-outline" type="button" @click="loadAttendance">Thử lại</button></div><div v-else-if="attendanceLoading && !attendance.length" class="state" role="status">Đang tải chấm công...</div><div v-else-if="!attendance.length" class="state">Không có chấm công phù hợp.</div>
        <div v-else class="table-wrapper"><table class="table"><thead><tr><th>Ngày / ca</th><th>Nhân viên</th><th>Thực tế</th><th>Hợp lệ</th><th>Muộn / sớm</th><th>OT</th><th>Phút duyệt</th><th>OT duyệt</th><th>Ghi chú</th><th>Tiền công</th><th></th></tr></thead><tbody><tr v-for="item in attendance" :key="item.shiftId"><td data-label="Ngày / ca">{{ item.shiftDate }}<small>{{ CODE_LABELS[item.shiftCode] }}</small></td><td data-label="Nhân viên">{{ item.staffName }}</td><td data-label="Thực tế">{{ item.actualMinutes }}</td><td data-label="Hợp lệ">{{ item.overlapEligibleMinutes }}</td><td data-label="Muộn / sớm">{{ item.lateMinutes }} / {{ item.earlyLeaveMinutes }}</td><td data-label="OT">{{ item.potentialOvertimeMinutes }}</td><td data-label="Phút duyệt"><input v-model.number="item.approvedMinutes" type="number" min="0" :max="item.overlapEligibleMinutes" aria-label="Phút duyệt"></td><td data-label="OT duyệt"><input v-model.number="item.approvedOvertimeMinutes" type="number" min="0" :max="item.potentialOvertimeMinutes" aria-label="Phút tăng ca duyệt"></td><td data-label="Ghi chú"><input v-model="item.attendanceNote" maxlength="500" aria-label="Ghi chú chấm công"></td><td data-label="Tiền công"><strong v-if="item.paySnapshotStatus === 'CALCULATED'">{{ money(item.totalPayAmount) }}<small>Đã tính theo snapshot</small></strong><span v-else-if="item.paySnapshotStatus === 'LEGACY_UNAVAILABLE'" class="truth legacy">Không có snapshot lịch sử</span><span v-else-if="item.effectiveRegularHourlyRate == null" class="truth missing">Chưa cấu hình mức công</span><strong v-else>{{ money(item.previewTotalPayAmount) }}<small>Dự kiến</small></strong></td><td data-label="Thao tác"><button class="btn btn-primary" type="button" :disabled="attendanceSavingId !== null || item.attendanceStatus === 'APPROVED' || item.effectiveRegularHourlyRate == null" @click="approve(item)">{{ attendanceSavingId === item.shiftId ? 'Đang duyệt...' : item.attendanceStatus === 'APPROVED' ? 'Đã duyệt' : 'Duyệt' }}</button></td></tr></tbody></table></div>
      </section>
    </template>
    <section v-else class="pay-rate-workspace rate-layout" aria-labelledby="rate-title"><div class="panel rate-form"><h2 id="rate-title">Thêm mức công</h2><label>Nhân viên<select v-model="rateUserId" class="form-select" @change="loadRates"><option value="">Chọn nhân viên</option><option v-for="user in staff" :key="user.userId" :value="String(user.userId)">{{ user.fullName }}</option></select></label><label>Hiệu lực từ<input v-model="rateForm.effectiveFrom" type="date"></label><label>Mức giờ thường<input v-model.number="rateForm.regularHourlyRate" type="number" min="0.01" step="0.01"></label><label>Mức giờ tăng ca<input v-model.number="rateForm.overtimeHourlyRate" type="number" min="0.01" step="0.01"></label><button class="btn btn-primary" :disabled="rateSaving || !rateUserId" @click="createRate">{{ rateSaving ? 'Đang thêm...' : 'Thêm mức công' }}</button><p v-if="rateError" class="rate-error" role="alert">{{ rateError }}</p></div><div class="panel pay-rate-history rate-history"><h2>Mức công nhân viên · Lịch sử hiệu lực</h2><div v-if="!rateUserId" class="rate-empty">Chọn nhân viên để xem lịch sử.</div><div v-else-if="!payRates.length" class="rate-empty">Chưa có mức công.</div><article v-for="rate in payRates" v-else :key="rate.payRateId"><strong>{{ rate.effectiveFrom }}</strong><span>Thường {{ money(rate.regularHourlyRate) }}/giờ</span><span>OT {{ money(rate.overtimeHourlyRate) }}/giờ</span></article><p class="rate-note">Mức mới chỉ áp dụng từ ngày hiệu lực; không thay đổi snapshot đã duyệt trước đó.</p></div></section>
  </main>
</template>

<style scoped>
.attendance-page{display:grid;gap:16px;color:var(--admin-foreground)}.page-header h1{margin:3px 0;font-size:28px;letter-spacing:-.04em}.page-header p{margin:0;color:var(--admin-muted)}.eyebrow{color:var(--admin-brand)!important;font-size:10px;font-weight:800;letter-spacing:.1em;text-transform:uppercase}.view-tabs{display:flex;gap:4px;border-bottom:1px solid var(--admin-hairline)}.view-tabs button{min-height:44px;padding:0 14px;border:0;border-bottom:2px solid transparent;background:transparent;color:var(--admin-muted);font-weight:700}.view-tabs button[aria-selected="true"]{border-color:var(--admin-brand);color:var(--admin-foreground)}.summary-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.summary-grid article,.panel{border:1px solid var(--admin-hairline);border-radius:14px;background:var(--admin-surface);box-shadow:var(--admin-card-shadow)}.summary-grid article{padding:17px}.summary-grid span{color:var(--admin-muted);font-size:11px}.summary-grid strong{display:block;margin-top:10px;font-size:22px;font-variant-numeric:tabular-nums}.panel{overflow:hidden}.toolbar{display:flex;align-items:end;gap:10px;flex-wrap:wrap;padding:16px;border-bottom:1px solid var(--admin-hairline)}.toolbar h2{margin:0 auto 0 0}.toolbar label,.rate-form label{display:grid;gap:5px;color:var(--admin-muted);font-size:11px;font-weight:700}.toolbar input,.toolbar select,.toolbar button,.table input,.table button,.rate-form input,.rate-form select{min-height:40px}.state{display:flex;min-height:220px;align-items:center;justify-content:center;gap:12px;color:var(--admin-muted)}.error,.rate-error{color:var(--admin-danger)}.table-wrapper{overflow-x:auto}.table{min-width:1080px}.table td small{display:block;color:var(--admin-muted);font-size:10px}.truth{display:inline-flex;padding:5px 8px;border-radius:7px;font-size:10px;font-weight:700}.truth.missing{background:var(--admin-danger-soft);color:var(--admin-danger)}.truth.legacy{background:var(--admin-surface-subtle);color:var(--admin-muted)}.rate-layout{display:grid;grid-template-columns:340px 1fr;gap:14px}.rate-form,.rate-history{padding:18px}.rate-form h2,.rate-history h2{margin:0 0 16px}.rate-form label{margin-bottom:12px}.rate-form .btn{width:100%}.rate-error{margin:12px 0 0}.rate-empty,.rate-note{color:var(--admin-muted);font-size:12px}.rate-history article{display:grid;grid-template-columns:120px 1fr 1fr;gap:12px;padding:14px 0;border-bottom:1px solid var(--admin-hairline)}.rate-history article span{color:var(--admin-muted)}.rate-note{margin-top:16px}.attendance-page :is(button,input,select):focus-visible{outline:3px solid rgba(255,116,72,.35);outline-offset:2px}@media(max-width:1000px){.summary-grid{grid-template-columns:repeat(2,1fr)}.rate-layout{grid-template-columns:1fr}}@media(max-width:700px){.toolbar,.toolbar label,.toolbar .btn{width:100%}.toolbar h2{width:100%}.table-wrapper{overflow:visible}.table{min-width:0}.table thead{display:none}.table,.table tbody,.table tr,.table td{display:block;width:100%}.table tr{padding:14px;border-top:1px solid var(--admin-hairline)}.table td{display:grid;grid-template-columns:110px minmax(0,1fr);gap:10px;align-items:center;padding:7px 0;border:0}.table td::before{content:attr(data-label);color:var(--admin-muted);font-size:12px;font-weight:700}.table input,.table button{width:100%}.rate-history article{grid-template-columns:1fr}}
</style>

<style scoped>
.attendance-page{gap:18px}.page-header{padding:14px 4px 8px}.page-header h1{font-size:clamp(30px,3vw,40px);line-height:1.08;letter-spacing:-.055em}.attendance-mode-tabs{gap:12px}.attendance-mode-tabs button{padding-inline:3px 16px}.attendance-summary-grid{gap:14px}.attendance-summary-grid article{min-height:126px;padding:20px;border-radius:var(--admin-panel-radius);box-shadow:var(--admin-card-shadow)}.attendance-summary-grid article strong{margin-top:16px;font-size:27px;letter-spacing:-.04em}.attendance-workspace,.pay-rate-workspace .panel{border-radius:var(--admin-panel-radius);box-shadow:var(--admin-card-shadow)}.attendance-toolbar{min-height:78px;padding:15px 18px}.attendance-toolbar h2{font-size:20px;letter-spacing:-.03em}.attendance-toolbar label{min-width:130px}.attendance-toolbar input,.attendance-toolbar select{border-color:var(--admin-hairline);border-radius:var(--admin-control-radius);background:var(--admin-surface-subtle)}.attendance-workspace .table-wrapper{border-top:1px solid var(--admin-hairline)}.attendance-workspace table th{padding:13px 14px;background:var(--admin-surface-subtle);color:var(--admin-muted);font-size:10px;letter-spacing:.05em;text-transform:uppercase}.attendance-workspace table td{padding:14px;border-color:var(--admin-hairline)}.attendance-workspace table input{border-color:var(--admin-hairline);border-radius:9px;background:#fff}.attendance-workspace table .btn-primary{min-height:40px;background:var(--admin-action)}.pay-rate-workspace{grid-template-columns:minmax(280px,.75fr) minmax(0,1.25fr);gap:14px}.rate-form,.pay-rate-history{padding:20px}.rate-form{position:relative;overflow:hidden}.rate-form::before{position:absolute;inset:0 0 auto;height:4px;background:var(--admin-brand);content:""}.rate-form h2,.pay-rate-history h2{font-size:20px;letter-spacing:-.03em}.rate-form label{gap:7px}.rate-form input,.rate-form select{border-color:var(--admin-hairline);border-radius:var(--admin-control-radius);background:var(--admin-surface-subtle)}.rate-form .btn-primary{min-height:44px;background:var(--admin-action)}.pay-rate-history{display:flex;min-height:420px;flex-direction:column}.pay-rate-history article{display:grid;grid-template-columns:130px 1fr 1fr;gap:12px;padding:16px 0;border-top:1px solid var(--admin-hairline)}.pay-rate-history article strong{color:var(--admin-brand-dark)}.rate-note{margin-top:auto!important;padding:13px;border:1px dashed rgba(244,91,42,.28);border-radius:12px;background:#fff9f5;color:var(--admin-muted)}@media(max-width:1000px){.attendance-summary-grid{grid-template-columns:repeat(2,1fr)}.pay-rate-workspace{grid-template-columns:1fr}}@media(max-width:760px){.attendance-toolbar{align-items:stretch;flex-direction:column}.attendance-toolbar h2{margin:0}.attendance-toolbar label{width:100%}.attendance-toolbar .btn{width:100%}.attendance-workspace .table-wrapper{overflow:visible}.attendance-workspace .table{display:block;min-width:0}.attendance-workspace thead{display:none}.attendance-workspace tbody{display:grid;gap:10px;padding:10px}.attendance-workspace tr{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:14px;border:1px solid var(--admin-hairline);border-radius:14px;background:#fff}.attendance-workspace td{display:grid;gap:4px;padding:0!important;border:0!important}.attendance-workspace td::before{color:var(--admin-muted);font-size:9px;font-weight:750;letter-spacing:.05em;text-transform:uppercase;content:attr(data-label)}.attendance-workspace td[data-label="Ghi chú"],.attendance-workspace td[data-label="Tiền công"],.attendance-workspace td[data-label="Thao tác"]{grid-column:1/-1}.attendance-workspace td[data-label="Thao tác"] .btn{width:100%}.pay-rate-history article{grid-template-columns:1fr}.pay-rate-history{min-height:320px}}@media(max-width:430px){.attendance-summary-grid{grid-template-columns:1fr}.attendance-summary-grid article{min-height:108px}.attendance-workspace tr{grid-template-columns:1fr}}
</style>
